raw_response:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "graph_structure",
      "expression": "1 <= ai < bi <= n and 1 <= ci <= m",
      "description": "Each edge connects two distinct vertices and has a unique color."
    },
    {
      "id": "no_multiple_edges",
      "expression": "not exists (ai, bi, ci), (aj, bj, cj) where ai < aj < bi and bi < bj and ci == cj",
      "description": "There are no multiple edges of the same color between two vertices."
    },
    {
      "id": "distinct_vertices",
      "expression": "ui != vi",
      "description": "The vertices in each query are distinct."
    }
  ],
  "postconditions": [
    {
      "id": "color_count",
      "expression": "len(answer) == q",
      "description": "The number of answers matches the number of queries."
    },
    {
      "id": "color_validity",
      "expression": "all(0 <= answer[i] <= m for i in range(q))",
      "description": "Each answer is a non-negative integer within the range of available colors."
    },
    {
      "id": "color_connectivity",
      "expression": "all(answer[i] == count_colors_connecting(ui, vi) for i in range(q))",
      "description": "Each answer is the count of colors that connect the given vertices ui and vi directly or indirectly."
    }
  ],
  "invariants": []
}
